import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { validateJob } from "./schema.mjs";

export function writeAtomic(filePath, value) {
  const validation = validateJob(value);
  if (!validation.valid) {
    throw new Error(`Job schema invalid: ${validation.errors.join(", ")}`);
  }
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const temporaryPath = `${filePath}.${process.pid}.${randomUUID().slice(0, 8)}.tmp`;
  fs.writeFileSync(temporaryPath, `${JSON.stringify(value, null, 2)}\n`, {
    encoding: "utf8",
    mode: 0o600,
  });
  fs.renameSync(temporaryPath, filePath);
}

export function validateManifest(manifest) {
  const errors = [];
  if (!manifest || typeof manifest !== "object") {
    return { valid: false, errors: ["Manifest must be a non-null object"] };
  }
  if (!manifest.schemaVersion) errors.push("Missing schemaVersion");
  if (!manifest.runId || typeof manifest.runId !== "string") errors.push("Missing or invalid runId");
  if (!manifest.state || !Object.values(RUN_STATES).includes(manifest.state)) {
    errors.push(`Invalid manifest state: ${manifest.state}`);
  }
  if (!manifest.project?.id) errors.push("Missing project.id");
  if (!manifest.project?.repository) errors.push("Missing project.repository");
  if (!manifest.task?.path) errors.push("Missing task.path");
  return { valid: errors.length === 0, errors };
}

import { timingSafeEqual, randomBytes } from "node:crypto";

export function authenticateRequest(req, expectedToken) {
  if (!expectedToken || typeof expectedToken !== "string") {
    return { authenticated: false, reason: "Server API token not configured" };
  }

  const extracted = extractTokenFromRequest(req);
  if (!extracted) {
    return { authenticated: false, reason: "Missing Authorization header or token" };
  }

  try {
    const expectedBuffer = Buffer.from(expectedToken, "utf8");
    const actualBuffer = Buffer.from(extracted, "utf8");
    if (expectedBuffer.length !== actualBuffer.length) {
      return { authenticated: false, reason: "Invalid API token" };
    }
    const matches = timingSafeEqual(expectedBuffer, actualBuffer);
    return matches
      ? { authenticated: true, reason: null }
      : { authenticated: false, reason: "Invalid API token" };
  } catch {
    return { authenticated: false, reason: "Token validation error" };
  }
}

export function validateOrigin(req) {
  const origin = req.headers["origin"] || req.headers["referer"];
  if (!origin || typeof origin !== "string") {
    return { valid: true, reason: null };
  }

  try {
    const parsed = new URL(origin);
    const hostname = parsed.hostname.toLowerCase();
    if (hostname === "127.0.0.1" || hostname === "localhost" || hostname === "[::1]") {
      return { valid: true, reason: null };
    }
    return { valid: false, reason: `Origin ${parsed.origin} is not allowed. Only localhost/127.0.0.1 is permitted.` };
  } catch {
    return { valid: false, reason: "Malformed Origin or Referer header" };
  }
}

export class DaemonWorkerPool {
  constructor({ runsRoot, maxParallelJobs = 2, pollIntervalMs = 1000 }) {
    this.runsRoot = runsRoot;
    this.maxParallelJobs = maxParallelJobs;
    this.pollIntervalMs = pollIntervalMs;
    this.activeWorkers = new Map(); // jobId -> workerPromise
    this.runningProjects = new Set(); // projectId (exclusive lock)
  }

  canScheduleProject(projectId) {
    return !this.runningProjects.has(projectId);
  }

  async processNext() {
    if (this.activeWorkers.size >= this.maxParallelJobs) return;
    const queuedJobs = listJobs(this.runsRoot).filter(j => j.state === JOB_STATES.QUEUED);

    for (const job of queuedJobs) {
      if (this.activeWorkers.size >= this.maxParallelJobs) break;
      if (this.canScheduleProject(job.projectId)) {
        this.runningProjects.add(job.projectId);
        const worker = this.executeJob(job).finally(() => {
          this.activeWorkers.delete(job.jobId);
          this.runningProjects.delete(job.projectId);
        });
        this.activeWorkers.set(job.jobId, worker);
      }
    }
  }
}

export function createWorktreeWorkspace({ repoPath, runsRoot, runId }) {
  const worktreeDir = path.join(runsRoot, "workspaces", runId);
  fs.mkdirSync(path.dirname(worktreeDir), { recursive: true });

  // Create detached worktree from current HEAD/baseline
  execFileSync("git", ["worktree", "add", "--detach", worktreeDir, "HEAD"], {
    cwd: repoPath,
    stdio: "pipe",
  });

  return {
    worktreeDir,
    cleanup: () => {
      try {
        execFileSync("git", ["worktree", "remove", "--force", worktreeDir], {
          cwd: repoPath,
          stdio: "pipe",
        });
      } catch {}
    }
  };
}

export function auditWorkspaceScope({ worktreeDir, allowedPaths }) {
  const output = execFileSync("git", ["status", "--porcelain"], {
    cwd: worktreeDir,
    encoding: "utf8",
  });

  const modifiedFiles = output
    .split("\n")
    .map(line => line.slice(3).trim())
    .filter(Boolean);

  const violations = modifiedFiles.filter(file => 
    !allowedPaths.some(allowed => file === allowed || file.startsWith(`${allowed}/`))
  );

  return {
    inScope: violations.length === 0,
    modifiedFiles,
    violations,
  };
}

export function createEventHub({ heartbeatIntervalMs = 15000 } = {}) {
  const clients = new Set();
  let heartbeatTimer = null;

  const startHeartbeat = () => {
    if (heartbeatTimer) return;
    heartbeatTimer = setInterval(() => {
      for (const client of clients) {
        try {
          client.res.write(`: heartbeat ${new Date().toISOString()}\n\n`);
        } catch {
          clients.delete(client);
        }
      }
    }, heartbeatIntervalMs);
    if (heartbeatTimer.unref) heartbeatTimer.unref();
  };

  const addClient = (req, res) => {
    res.writeHead(200, {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      "Connection": "keep-alive",
      "Access-Control-Allow-Origin": "*",
      "X-Accel-Buffering": "no",
    });

    const client = { req, res, connectedAt: new Date().toISOString() };
    clients.add(client);
    res.write(`event: connected\ndata: ${JSON.stringify({ connectedAt: client.connectedAt })}\n\n`);

    if (clients.size === 1) startHeartbeat();

    req.on("close", () => {
      clients.delete(client);
      if (clients.size === 0 && heartbeatTimer) {
        clearInterval(heartbeatTimer);
        heartbeatTimer = null;
      }
    });

    return client;
  };

  const broadcast = (eventType, payload = {}) => {
    const data = typeof payload === "string" ? payload : JSON.stringify(payload);
    const message = `event: ${eventType}\ndata: ${data}\n\n`;
    for (const client of clients) {
      try {
        client.res.write(message);
      } catch {
        clients.delete(client);
      }
    }
  };

  return { addClient, broadcast, getClientCount: () => clients.size };
}
